// A test server for the player's reader and downloader (DESIGN.md §10.4; the iron-clad
// spec §4.7). It serves a file of generated bytes behind `Range`, as the content route
// does, and can be told to misbehave as a network and a server do: to answer with a
// status, to break the connection part-way, to be slow, to ignore `Range`. Each fault
// applies to one request, the next one that has none before it, in the order they were
// given; the requests after the faults are served as they are asked for. The file is never
// held: its bytes are `byteAt(seed, offset)`, so a test can say what any range must be.
// It is for tests only (it uses `node:http`), so the package does not export it.

import { createServer } from 'node:http'
import type { IncomingMessage, ServerResponse } from 'node:http'

/** The size of the pieces a body is sent in, and the pieces a delay waits between. */
const CHUNK_BYTES = 64 * 1024

/**
 * What goes wrong with the next request:
 * - `drop`: the headers and `afterBytes` bytes of the body are sent, then the connection is
 *   broken (a body that is shorter than `afterBytes` is sent whole and not cut).
 * - `status`: that status and an empty body, with `Retry-After` when it is given.
 * - `delay`: `ms` is waited between the 64 KiB pieces of the response, which are the only
 *   pieces of a file of 64 KiB or less (so that it has no gap to wait in).
 * - `ignore-range`: the whole file as a `200`, whatever the `Range` said.
 */
export type Fault =
  | { kind: 'drop'; afterBytes: number }
  | { kind: 'status'; status: number; retryAfter?: string }
  | { kind: 'delay'; ms: number }
  | { kind: 'ignore-range' }

export interface RangeServerOptions {
  /** The size of the file, in bytes. */
  size: number
  /** Which file it is: the bytes of two seeds are unrelated. */
  seed: number
  faults?: Fault[]
  /** Waited between the 64 KiB pieces of every response that has no `delay` fault: a slow link. */
  chunkDelayMs?: number
}

export interface RangeServer {
  /** Where the file is: `http://127.0.0.1:<port>/file.bin`. Any path, and any query, is served. */
  url: string
  /** Each request's `Range` header, null when it had none, in the order they came. */
  requests: { range: string | null }[]
  /** How many responses have been started and not yet ended or lost: those of clients that are still reading. */
  openResponses(): number
  /** Ends the open responses and stops listening. It resolves when the server is closed, and may be called again. */
  close(): Promise<void>
}

/**
 * The byte at `offset` of the file that `seed` names: a pure function, a small integer hash
 * (the finalizer of MurmurHash3) of the offset mixed with the seed. Nothing in it repeats at
 * a power of two or at 2^32, so a read at a wrong offset does not read the right bytes by
 * chance. It is cheap enough to fill 64 MiB in a fraction of a second.
 */
export function byteAt(seed: number, offset: number): number {
  const low = offset >>> 0
  const high = Math.floor(offset / 0x1_0000_0000) >>> 0
  let hash = low ^ Math.imul(seed | 0, 0x9e3779b1) ^ Math.imul(high + 1, 0x7feb352d)
  hash = Math.imul(hash ^ (hash >>> 16), 0x85ebca6b)
  hash = Math.imul(hash ^ (hash >>> 13), 0xc2b2ae35)
  return (hash ^ (hash >>> 16)) & 0xff
}

/** The bytes of the file from `start` up to, not including, `end`. */
function fill(seed: number, start: number, end: number): Uint8Array {
  const bytes = new Uint8Array(end - start)
  for (let at = 0; at < bytes.length; at += 1) bytes[at] = byteAt(seed, start + at)
  return bytes
}

/** Waits `ms`, or until the response is over: the timer does not outlive a client that went away. */
function pause(response: ServerResponse, ms: number): Promise<void> {
  return new Promise((resolve) => {
    if (response.destroyed) {
      resolve()
      return
    }
    const done = (): void => {
      clearTimeout(timer)
      response.off('close', done)
      resolve()
    }
    const timer = setTimeout(done, ms)
    response.once('close', done)
  })
}

/** Waits until the response can take more, or is over. */
function drained(response: ServerResponse): Promise<void> {
  return new Promise((resolve) => {
    if (response.destroyed) {
      resolve()
      return
    }
    const done = (): void => {
      response.off('drain', done)
      response.off('close', done)
      resolve()
    }
    response.once('drain', done)
    response.once('close', done)
  })
}

/** Waits for a write to leave for the socket (or to fail: the response is over then). */
function written(response: ServerResponse, chunk: Uint8Array): Promise<void> {
  return new Promise((resolve) => {
    response.write(chunk, () => {
      resolve()
    })
  })
}

/**
 * What a `Range` header asks for: the first byte and the last byte, inclusive and clamped to
 * the file, or why it cannot be answered. Only `bytes=a-` and `bytes=a-b` are understood.
 */
function parseRange(
  header: string,
  size: number,
): { start: number; last: number } | 'unreadable' | 'unsatisfiable' {
  const match = /^bytes=(\d+)-(\d*)$/.exec(header)
  if (match === null) return 'unreadable'
  const start = Number(match[1])
  const last = match[2] === '' ? size - 1 : Math.min(Number(match[2]), size - 1)
  if (!Number.isSafeInteger(start) || start >= size || last < start) return 'unsatisfiable'
  return { start, last }
}

/**
 * Sends `[start, end)` of the file in 64 KiB pieces, waiting `delayMs` between them, with
 * back pressure, and stops at once when the client goes away. With `dropAfter`, the
 * connection is broken once that many bytes are on their way, if the body is longer.
 */
async function sendBody(
  response: ServerResponse,
  seed: number,
  start: number,
  end: number,
  delayMs: number,
  dropAfter: number | null,
): Promise<void> {
  const drop = dropAfter !== null && dropAfter < end - start
  const limit = drop ? start + dropAfter : end
  response.flushHeaders()
  let position = start
  while (position < limit) {
    if (position > start && delayMs > 0) await pause(response, delayMs)
    if (response.destroyed) return
    const to = Math.min(position + CHUNK_BYTES, limit)
    const chunk = fill(seed, position, to)
    position = to
    if (drop && position === limit) {
      // The bytes are let go before the connection is: a destroyed socket forgets what it has not sent.
      await written(response, chunk)
    } else if (!response.write(chunk)) {
      await drained(response)
    }
  }
  if (drop) {
    // With no bytes to wait for, the headers still have to leave first.
    if (limit === start) await new Promise((resolve) => setImmediate(resolve))
    response.destroy()
    return
  }
  response.end()
}

/** Answers a request: the file, a range of it, or what the next fault says. */
async function answer(
  request: IncomingMessage,
  response: ServerResponse,
  options: { size: number; seed: number; chunkDelayMs: number },
  fault: Fault | undefined,
): Promise<void> {
  const { size, seed, chunkDelayMs } = options
  if (request.method !== 'GET') {
    response.writeHead(405, { Allow: 'GET', 'Content-Length': '0' })
    response.end()
    return
  }
  if (fault?.kind === 'status') {
    response.writeHead(fault.status, {
      'Content-Length': '0',
      ...(fault.retryAfter === undefined ? {} : { 'Retry-After': fault.retryAfter }),
    })
    response.end()
    return
  }
  const delayMs = fault?.kind === 'delay' ? fault.ms : chunkDelayMs
  const dropAfter = fault?.kind === 'drop' ? fault.afterBytes : null
  const header = request.headers.range
  if (header === undefined || fault?.kind === 'ignore-range') {
    response.writeHead(200, {
      'Content-Length': String(size),
      'Content-Type': 'application/octet-stream',
      'Accept-Ranges': 'bytes',
    })
    await sendBody(response, seed, 0, size, delayMs, dropAfter)
    return
  }
  const range = parseRange(header, size)
  if (range === 'unreadable') {
    response.writeHead(400, { 'Content-Length': '0' })
    response.end()
    return
  }
  if (range === 'unsatisfiable') {
    response.writeHead(416, { 'Content-Length': '0', 'Content-Range': `bytes */${String(size)}` })
    response.end()
    return
  }
  const { start, last } = range
  response.writeHead(206, {
    'Content-Length': String(last - start + 1),
    'Content-Range': `bytes ${String(start)}-${String(last)}/${String(size)}`,
    'Content-Type': 'application/octet-stream',
    'Accept-Ranges': 'bytes',
  })
  await sendBody(response, seed, start, last + 1, delayMs, dropAfter)
}

/** Starts the server on 127.0.0.1, on a port the system chooses. */
export async function startRangeServer(options: RangeServerOptions): Promise<RangeServer> {
  const { size, seed, chunkDelayMs = 0 } = options
  if (!Number.isSafeInteger(size) || size < 0) {
    throw new RangeError(`${size} is not the size of a file`)
  }
  const faults = [...(options.faults ?? [])]
  const requests: { range: string | null }[] = []
  let open = 0

  const server = createServer((request, response) => {
    requests.push({ range: request.headers.range ?? null })
    open += 1
    response.once('close', () => {
      open -= 1
    })
    // A client that goes away makes writes fail: that is its business, not the server's.
    request.on('error', () => undefined)
    response.on('error', () => undefined)
    answer(request, response, { size, seed, chunkDelayMs }, faults.shift()).catch(() => {
      response.destroy()
    })
  })

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', () => {
      server.off('error', reject)
      resolve()
    })
  })
  const address = server.address()
  if (address === null || typeof address === 'string') {
    throw new Error('the test server has no port')
  }

  let closing: Promise<void> | null = null
  return {
    url: `http://127.0.0.1:${String(address.port)}/file.bin`,
    requests,
    openResponses: () => open,
    close() {
      closing ??= new Promise<void>((resolve, reject) => {
        server.close((error) => {
          if (error === undefined) resolve()
          else reject(error)
        })
        // A client that keeps its connection alive would hold the close up until its timeout.
        server.closeAllConnections()
      })
      return closing
    },
  }
}
